codes.javascript:
// use BigInt when the modulus is large, so products do not lose precision
const addMod = (a, b, m) => ((a % m) + (b % m)) % m;
const subMod = (a, b, m) => ((a % m) - (b % m) + m) % m;
const mulMod = (a, b, m) => (BigInt(a) * BigInt(b)) % BigInt(m);
